module clkgenerator(
    output clk
);
    parameter PERIOD = 10;
    reg [31:0] cnt = 0;
    reg clk_reg = 0;
    assign clk = clk_reg;
    initial begin
        clk_reg = 0;
    end
    always @(posedge clk_reg) begin
        if(cnt >= PERIOD/2 - 1) begin
            cnt <= 0;
            clk_reg <= ~clk_reg;
        end
        else begin
            cnt <= cnt + 1;
        end
    end
endmodule
